#include "zed_capture/jpeg_files.hpp"
#include <boost/make_shared.hpp>
#include <boost/weak_ptr.hpp>
#include <cassert>
#include <iostream>
static capture::ShadowInput input(int id){auto m=boost::make_shared<zed_capture::VideoStamp>();m->pair_id=id;m->v4l2_sequence=id;m->header.seq=id;m->header.stamp.fromNSec(123000000000ULL+id*33333333ULL);m->v4l2_sec=m->header.stamp.sec;m->v4l2_usec=m->header.stamp.nsec/1000;m->payload_valid=true;auto l=boost::make_shared<sensor_msgs::Image>(),r=boost::make_shared<sensor_msgs::Image>();l->header=r->header=m->header;return {m,l,r,capture::now(CLOCK_MONOTONIC),true};}
static capture::FileEncoded fake(const capture::ShadowInput&){capture::FileEncoded x;x.left={255,216,255,217};x.right=x.left;x.timing={1,2,4,4,true};return x;}
static std::string read(const std::string&p){std::ifstream f(p);return {std::istreambuf_iterator<char>(f),{}};}
int main(int argc,char**argv){assert(argc==2);std::string root=argv[1];assert(!mkdir(root.c_str(),0750));auto path=[&](const char*n){auto p=root+'/'+n;assert(!mkdir(p.c_str(),0750));return p;};
 {auto p=path("normal_short_write");capture::JpegFiles w(p,fake,[]{},1000,[](int fd,const void*b,size_t n){return ::write(fd,b,std::min(n,size_t(1)));});auto in=input(1);auto h=in.left->header;w.submit(in);w.finish();assert(!w.failed());assert(in.left->header==h);assert(read(p+"/camera/left/000000/000000000001.jpg").size()==4);assert(read(p+"/jpeg_files_summary.json").find("\"final_synced\":true")!=std::string::npos);w.finish();}
 {auto p=path("right_disk_error");int fd_first=-1,calls=0;capture::JpegFiles w(p,fake,[]{},1000,[&](int fd,const void*b,size_t n)->ssize_t{if(calls++==0)return ::write(fd,b,n);errno=ENOSPC;return -1;});w.submit(input(1));w.finish();assert(w.failed());auto index=read(p+"/frames.csv");assert(index.find("WRITE_FAILED")!=std::string::npos);assert(read(p+"/camera/left/000000/000000000001.jpg").size()==4);assert(read(p+"/camera/right/000000/000000000001.jpg").empty());}
 {auto p=path("zero_write");capture::JpegFiles w(p,fake,[]{},1000,[](int,const void*,size_t)->ssize_t{return 0;});w.submit(input(1));w.finish();assert(w.failed());assert(read(p+"/frames.csv").find("ZERO_SHORT_WRITE")!=std::string::npos);}
 {auto p=path("encode_failure");capture::JpegFiles w(p,[](const capture::ShadowInput&)->capture::FileEncoded{throw std::runtime_error("SYNTHETIC_CODEC_ERROR");},[]{});w.submit(input(1));w.finish();assert(w.failed());assert(read(p+"/frames.csv").find("ENCODE_FAILED")!=std::string::npos);}
 {auto p=path("encode_queue_full_ownership");std::promise<void> entered,release;auto gate=release.get_future().share();std::atomic<int> calls{0};capture::JpegFiles w(p,[&](const capture::ShadowInput&i){if(calls++==0)entered.set_value();gate.wait();return fake(i);},[]{});auto in=input(1);boost::weak_ptr<const sensor_msgs::Image> weak=in.left;w.submit(in);in={};entered.get_future().wait();assert(!weak.expired());for(int i=2;i<=6;i++)w.submit(input(i));release.set_value();w.finish();assert(weak.expired());assert(w.failed());assert(read(p+"/frames.csv").find("ENCODE_QUEUE_REJECTED")!=std::string::npos);}
 {auto p=path("writer_queue_full");std::promise<void> entered,release;auto gate=release.get_future().share();std::atomic<int> calls{0};capture::JpegFiles w(p,fake,[]{},1000,[&](int fd,const void*b,size_t n){if(calls++==0){entered.set_value();gate.wait();}return ::write(fd,b,n);});w.submit(input(1));entered.get_future().wait();for(int i=2;i<=19;i++){w.submit(input(i));std::this_thread::sleep_for(std::chrono::milliseconds(5));}release.set_value();w.finish();assert(w.failed());assert(read(p+"/frames.csv").find("WRITE_QUEUE_REJECTED")!=std::string::npos);}
 {auto p=path("preparation_failure");bool caught=false;try{capture::JpegFiles w(p,fake,[]{throw std::runtime_error("SYNTHETIC_PREP_FAIL");});}catch(...){caught=true;}assert(caught);}
 {auto p=path("no_overwrite");capture::JpegFiles w(p,fake,[]{});w.finish();bool caught=false;try{capture::JpegFiles other(p,fake,[]{});}catch(...){caught=true;}assert(caught);}
 {auto p=path("shard_boundary");capture::JpegFiles w(p,fake,[]{});w.submit(input(1000));std::this_thread::sleep_for(std::chrono::milliseconds(10));w.submit(input(1001));w.finish();assert(!w.failed());assert(access((p+"/camera/right/000000/000000001000.jpg").c_str(),F_OK)==0);assert(access((p+"/camera/right/000001/000000001001.jpg").c_str(),F_OK)==0);}
 std::cout<<"SYNTHETIC PASS: disk/zero/short writes, partial pair, bounded encode/write queues, ownership, drain, warmup failure, no overwrite, sharding\n";
}
